import os
import deepgram

def diarized_transcript(payload, config=None):
    config = config or {}
    deepgram_api_key = os.environ.get("DEEPGRAM_API_KEY")
    if not deepgram_api_key:
        raise ValueError("DEEPGRAM_API_KEY environment variable not set.")

    deepgram_client = deepgram.DeepgramClient(deepgram_api_key)

    if isinstance(payload, str) and (payload.startswith("http://") or payload.startswith("https://")):
        # Assuming payload is a URL to an audio file
        source = {'url': payload}
    else:
        # Assuming payload is raw audio data (e.g., bytes)
        source = {'buffer': payload, 'mimetype': config.get("mimetype", "audio/wav")}

    response = deepgram_client.listen.prerecorded.v("1").transcribe_file(
        source,
        {
            "diarize": True,
            "smart_format": True,
            "model": config.get("model", "meeting"),
            "utt_split": True
            # Other parameters can be added from config if needed
        }
    )

    # Extracting and normalizing the transcript and diarization
    paragraphs = []
    if response and response.results and response.results.channels:
        for channel in response.results.channels:
            for utterance in channel.alternatives[0].paragraphs.paragraphs:
                speaker_tag = f"[Speaker {utterance.speaker}]" if utterance.speaker is not None else "[Unknown Speaker]"
                paragraphs.append(f"{speaker_tag} {utterance.transcript}")

    result = {"paragraphs": paragraphs}
    return result
